type JsonObject = Record<string, any>;

export interface ClientGeneratorOptions {
  /** Module specifier, relative to the generated file, that exports the models. */
  readonly models: string;
}

/** Generate a small fetch client from framework OpenAPI metadata. */
export function generateClient(
  document: JsonObject,
  options: ClientGeneratorOptions,
): string {
  if (!document || typeof document !== "object" || !document.paths) {
    throw new TypeError("The input is not an OpenAPI document with paths");
  }
  if (!options.models.trim()) {
    throw new TypeError("A model module specifier is required");
  }

  const schemas: Record<string, JsonObject> =
    document.components?.schemas ?? {};
  const modelAliases = createModelAliases(schemas);
  const usedNames = new Set<string>();
  const methods: string[] = [];
  const imports = new Set<string>();

  for (const [path, pathItem] of Object.entries<JsonObject>(document.paths)) {
    for (const [method, operation] of Object.entries<JsonObject>(pathItem)) {
      if (!httpMethods.has(method.toLowerCase()) || !operation) continue;
      const name = createMethodName(operation.operationId, method, path);
      if (usedNames.has(name)) {
        throw new TypeError(`Duplicate generated client method name: ${name}`);
      }
      usedNames.add(name);
      methods.push(
        generateOperation(
          path,
          method.toUpperCase(),
          operation,
          schemas,
          modelAliases,
          imports,
          name,
        ),
      );
    }
  }

  const importLine = [...imports].sort().join(", ");
  return `/* Generated by @framework/client. Do not edit. */
import { validateModel } from "@framework/core";
import { createClient } from "@framework/client";
import type { ClientOptions } from "@framework/client";
${importLine ? `import { ${importLine} } from ${JSON.stringify(options.models)};\n` : ""}
export class ApiError extends Error {
  constructor(readonly status: number, readonly body: unknown) {
    super("HTTP request failed with status " + status);
    this.name = "ApiError";
  }
}

export function createApiClient(options: ClientOptions = {}) {
  const client = createClient(options);
  return {
${methods.map((methodSource) => indent(methodSource, 4)).join(",\n")}
  };
}

function appendQuery(searchParams: URLSearchParams, name: string, value: unknown) {
  if (value === undefined || value === null) return;
  if (Array.isArray(value)) {
    for (const item of value) searchParams.append(name, String(item));
  } else {
    searchParams.append(name, String(value));
  }
}
`;
}

const httpMethods = new Set([
  "get",
  "put",
  "post",
  "delete",
  "options",
  "head",
  "patch",
  "trace",
]);

function generateOperation(
  path: string,
  method: string,
  operation: JsonObject,
  schemas: Record<string, JsonObject>,
  modelAliases: Map<string, string>,
  imports: Set<string>,
  methodName: string,
) {
  const clientMetadata = operation["x-framework-client"] ?? {};
  const requestModelRef = clientMetadata.requestModel?.$ref as
    string | undefined;
  const requestModel = requestModelRef
    ? modelAliases.get(requestModelRef)
    : undefined;
  if (requestModelRef && !requestModel) {
    throw new TypeError(`No shared model is mapped for ${requestModelRef}`);
  }
  if (requestModel) imports.add(requestModel);

  const fields: Array<{ property: string; source: string; name: string }> =
    clientMetadata.fields ?? [];
  const parameters = mergeParameters(operation.parameters ?? []);
  const cookieParameter = parameters.find(
    (parameter) => parameter.in === "cookie",
  );
  if (cookieParameter) {
    throw new TypeError(
      `${method} ${path} uses a cookie parameter; cookie-based API parameters are not supported by the generated fetch client`,
    );
  }
  if (requestModel) {
    for (const parameter of parameters) {
      if (
        !fields.some(
          (field) =>
            field.source === parameter.in && field.name === parameter.name,
        )
      ) {
        throw new TypeError(
          `${method} ${path} has an OpenAPI parameter ${parameter.in}:${parameter.name} not represented by its request model`,
        );
      }
    }
  }

  const bodyMetadata = clientMetadata.body;
  const bodyRef = bodyMetadata?.model?.$ref as string | undefined;
  const bodyModel = bodyRef ? modelAliases.get(bodyRef) : undefined;
  if (bodyRef && !bodyModel) {
    throw new TypeError(`No shared model is mapped for ${bodyRef}`);
  }
  if (bodyModel) imports.add(bodyModel);

  const requestBody = operation.requestBody;
  const requestContent = requestBody?.content;
  const requestContentType = requestContent
    ? Object.keys(requestContent)[0]
    : undefined;
  if (requestContentType && !isJsonContentType(requestContentType)) {
    throw new TypeError(
      `${method} ${path} uses unsupported request content type ${requestContentType}; the generated client currently supports JSON bodies`,
    );
  }
  const requestSchema = requestContentType
    ? requestContent[requestContentType]?.schema
    : undefined;
  const bodyProperty = bodyMetadata?.property ?? "body";

  const hasInput = Boolean(requestModel || parameters.length || requestBody);
  let inputType = "";
  if (requestModel) {
    inputType = requestModel;
  } else if (hasInput) {
    inputType = createInputType(
      parameters,
      requestBody,
      bodyModel,
      requestSchema,
      schemas,
      modelAliases,
      imports,
    );
  }

  const responseType = getResponseType(
    operation.responses ?? {},
    modelAliases,
    imports,
  );
  const lines: string[] = [];
  lines.push(
    `${methodName}: async (${hasInput ? `input: ${inputType}` : ""}): Promise<${responseType}> => {`,
  );

  if (requestModel) {
    lines.push("  const requestInput: Record<string, unknown> = {};");
    for (const field of fields) {
      lines.push(
        `  if (Object.hasOwn(input, ${JSON.stringify(field.property)}) && input[${JSON.stringify(field.property)}] !== undefined) requestInput[${JSON.stringify(field.property)}] = input[${JSON.stringify(field.property)}];`,
      );
    }
    if (bodyModel) {
      lines.push(
        `  const serializedBodyInput = JSON.stringify((input as Record<string, unknown>)[${JSON.stringify(bodyProperty)}]);`,
      );
      lines.push(
        "  const bodyInput = serializedBodyInput === undefined ? undefined : JSON.parse(serializedBodyInput);",
      );
      lines.push(
        `  if (Object.hasOwn(input, ${JSON.stringify(bodyProperty)})) requestInput[${JSON.stringify(bodyProperty)}] = bodyInput;`,
      );
    }
    lines.push(
      `  const request = validateModel(requestInput, ${requestModel});`,
    );
  }
  if (bodyModel) {
    if (requestModel) {
      lines.push(`  const body = request[${JSON.stringify(bodyProperty)}];`);
    } else {
      lines.push("  const serializedBodyInput = JSON.stringify(input.body);");
      lines.push(
        "  const bodyInput = serializedBodyInput === undefined ? undefined : JSON.parse(serializedBodyInput);",
      );
      lines.push(`  const body = validateModel(bodyInput, ${bodyModel});`);
    }
  }

  const pathExpression = createPathExpression(
    path,
    parameters,
    fields,
    Boolean(requestModel),
  );
  lines.push(
    `  const url = new URL(${pathExpression}, options.baseUrl ?? globalThis.location?.origin ?? "http://localhost");`,
  );
  for (const [index, parameter] of parameters.entries()) {
    const access = getParameterAccess(parameter, fields, Boolean(requestModel));
    if (parameter.in === "query") {
      lines.push(
        `  appendQuery(url.searchParams, ${JSON.stringify(parameter.name)}, ${access});`,
      );
    } else if (parameter.in === "header") {
      // Header setup is emitted below, preserving repeated values as comma-separated.
      lines.push(`  const header_${index} = ${access};`);
    }
  }
  lines.push("  const headers = new Headers(options.headers);");
  for (const [index, parameter] of parameters.entries()) {
    if (parameter.in !== "header") continue;
    const local = `header_${index}`;
    lines.push(
      `  if (${local} !== undefined) headers.set(${JSON.stringify(parameter.name)}, Array.isArray(${local}) ? ${local}.join(",") : String(${local}));`,
    );
  }
  if (requestContentType) {
    lines.push(
      `  headers.set("content-type", ${JSON.stringify(requestContentType)});`,
    );
  }

  const bodyExpression = bodyModel
    ? "JSON.stringify(body)"
    : requestBody
      ? "JSON.stringify(input.body)"
      : undefined;
  lines.push(
    `  const response = await client.request(url.toString(), { method: ${JSON.stringify(method)}, headers${bodyExpression ? `, body: ${bodyExpression}` : ""} });`,
  );
  lines.push("  if (!response.ok) {");
  lines.push("    let errorBody: unknown;");
  lines.push(
    "    try { errorBody = await response.json(); } catch { errorBody = undefined; }",
  );
  lines.push("    throw new ApiError(response.status, errorBody);");
  lines.push("  }");
  if (responseType === "void") {
    lines.push("  return undefined;");
  } else {
    lines.push(
      "  if (response.status === 204 || response.status === 304) return undefined as " +
        responseType +
        ";",
    );
    lines.push("  return await response.json() as " + responseType + ";");
  }
  lines.push("}");
  return lines.join("\n");
}

function createInputType(
  parameters: JsonObject[],
  requestBody: JsonObject | undefined,
  bodyModel: string | undefined,
  bodySchema: JsonObject | undefined,
  schemas: Record<string, JsonObject>,
  modelAliases: Map<string, string>,
  imports: Set<string>,
) {
  const groups = ["path", "query", "header"] as const;
  const properties: string[] = [];
  for (const group of groups) {
    const groupParameters = parameters.filter(
      (parameter) => parameter.in === group,
    );
    if (!groupParameters.length) continue;
    const required = groupParameters.some((parameter) => parameter.required);
    const fields = groupParameters.map(
      (parameter) =>
        `${JSON.stringify(parameter.name)}${parameter.required ? "" : "?"}: ${schemaToType(parameter.schema ?? {}, schemas, modelAliases, imports)}`,
    );
    properties.push(`${group}${required ? "" : "?"}: { ${fields.join("; ")} }`);
  }
  if (requestBody) {
    const type =
      bodyModel ??
      schemaToType(bodySchema ?? {}, schemas, modelAliases, imports);
    properties.push(
      `body${requestBody.required === false ? "?" : ""}: ${type}`,
    );
  }
  return `{ ${properties.join("; ")} }`;
}

function getResponseType(
  responses: Record<string, JsonObject>,
  modelAliases: Map<string, string>,
  imports: Set<string>,
) {
  const successful = Object.entries(responses).filter(([status]) =>
    /^(?:2\d\d|2XX)$/.test(status),
  );
  if (!successful.length) return "void";
  const types = successful.map(([, response]) => {
    const content = response.content;
    if (!content) return "void";
    const contentType = Object.keys(content)[0];
    if (!contentType || !isJsonContentType(contentType)) {
      throw new TypeError(
        `Unsupported successful response content type ${contentType ?? "(empty)"}`,
      );
    }
    return schemaToType(
      content[contentType]?.schema ?? {},
      {},
      modelAliases,
      imports,
    );
  });
  return [...new Set(types)].join(" | ");
}

function schemaToType(
  schema: JsonObject,
  schemas: Record<string, JsonObject>,
  modelAliases: Map<string, string>,
  imports: Set<string>,
): string {
  if (schema.$ref) {
    const alias = modelAliases.get(schema.$ref);
    if (alias) {
      imports.add(alias);
      return alias;
    }
    const name = schema.$ref.split("/").at(-1)!;
    const target = schemas[name];
    if (target) return schemaToType(target, schemas, modelAliases, imports);
    return "unknown";
  }
  if (schema.const !== undefined) return JSON.stringify(schema.const);
  if (Array.isArray(schema.enum))
    return (
      schema.enum.map((value: unknown) => JSON.stringify(value)).join(" | ") ||
      "never"
    );
  const alternatives = schema.anyOf ?? schema.oneOf ?? schema.allOf;
  if (Array.isArray(alternatives)) {
    const separator = schema.allOf ? " & " : " | ";
    return alternatives
      .map((part: JsonObject) =>
        schemaToType(part, schemas, modelAliases, imports),
      )
      .join(separator);
  }
  if (schema.type === "array") {
    const itemType = schemaToType(
      schema.items ?? {},
      schemas,
      modelAliases,
      imports,
    );
    return `(${itemType})[]`;
  }
  if (schema.type === "object" || schema.properties) {
    const required = new Set<string>(schema.required ?? []);
    const properties = Object.entries<JsonObject>(schema.properties ?? {}).map(
      ([name, property]) =>
        `${JSON.stringify(name)}${required.has(name) ? "" : "?"}: ${schemaToType(property, schemas, modelAliases, imports)}`,
    );
    if (
      schema.additionalProperties &&
      typeof schema.additionalProperties === "object"
    ) {
      properties.push(
        `[key: string]: ${schemaToType(schema.additionalProperties, schemas, modelAliases, imports)}`,
      );
    }
    return properties.length
      ? `{ ${properties.join("; ")} }`
      : "Record<string, unknown>";
  }
  if (Array.isArray(schema.type)) {
    return schema.type.map((type: string) => primitiveType(type)).join(" | ");
  }
  return primitiveType(schema.type);
}

function primitiveType(type: string | undefined) {
  switch (type) {
    case "string":
      return "string";
    case "integer":
    case "number":
      return "number";
    case "boolean":
      return "boolean";
    case "null":
      return "null";
    case "object":
      return "Record<string, unknown>";
    case "array":
      return "unknown[]";
    default:
      return "unknown";
  }
}

function createPathExpression(
  path: string,
  parameters: JsonObject[],
  fields: Array<{ property: string; source: string; name: string }>,
  hasRequestModel: boolean,
) {
  const parts = path.split(/(\{[^{}]+\})/g);
  const expression = parts.map((part) => {
    const match = /^\{([^{}]+)\}$/.exec(part);
    if (!match) return escapeTemplateLiteral(part);
    const name = match[1]!;
    const parameter = parameters.find(
      (item) => item.in === "path" && item.name === name,
    );
    const access = parameter
      ? getParameterAccess(parameter, fields, hasRequestModel)
      : "undefined";
    if (access === "undefined")
      throw new TypeError(`Path parameter ${name} is not declared`);
    return `\${encodeURIComponent(String(${access}))}`;
  });
  return "`" + expression.join("") + "`";
}

function getParameterAccess(
  parameter: JsonObject,
  fields: Array<{ property: string; source: string; name: string }>,
  hasRequestModel: boolean,
) {
  if (hasRequestModel) {
    const field = fields.find(
      (item) => item.source === parameter.in && item.name === parameter.name,
    );
    return field ? `request[${JSON.stringify(field.property)}]` : "undefined";
  }
  const group = parameter.in === "header" ? "header" : parameter.in;
  return `input.${group}?.[${JSON.stringify(parameter.name)}]`;
}

function mergeParameters(parameters: JsonObject[]) {
  const merged = new Map<string, JsonObject>();
  for (const parameter of parameters) {
    if (!parameter || typeof parameter.name !== "string") continue;
    merged.set(`${parameter.in}:${parameter.name}`, parameter);
  }
  return [...merged.values()];
}

function createModelAliases(schemas: Record<string, JsonObject>) {
  const result = new Map<string, string>();
  const names = new Map<string, number>();
  for (const [schemaName, schema] of Object.entries(schemas)) {
    const className = schema["x-framework-model"];
    if (typeof className !== "string" || !className) continue;
    const count = names.get(className) ?? 0;
    if (count > 0) {
      throw new TypeError(
        `Multiple OpenAPI models use the exported TypeScript name ${className}; expose uniquely named model classes to generate a client`,
      );
    }
    names.set(className, count + 1);
    const alias = className;
    result.set(`#/components/schemas/${schemaName}`, alias);
  }
  return result;
}

function createMethodName(operationId: unknown, method: string, path: string) {
  const raw =
    typeof operationId === "string" && operationId
      ? operationId
      : `${method.toLowerCase()}_${path.replace(/[{}:]/g, "").replace(/[^A-Za-z0-9]+/g, "_")}`;
  const identifier = safeIdentifier(raw);
  return /^[A-Za-z_$]/.test(identifier)
    ? identifier
    : `operation_${identifier}`;
}

function safeIdentifier(value: string) {
  return value.replace(/[^A-Za-z0-9_$]/g, "_");
}

function escapeTemplateLiteral(value: string) {
  return value
    .replaceAll("\\", "\\\\")
    .replaceAll("`", "\\`")
    .replaceAll("${", "\\${");
}

function isJsonContentType(contentType: string) {
  return contentType === "application/json" || contentType.includes("+json");
}

function indent(value: string, spaces: number) {
  const prefix = " ".repeat(spaces);
  return value
    .split("\n")
    .map((line) => `${prefix}${line}`)
    .join("\n");
}
